def calc_entropies_per_sites(alignment, alphabet_size=None):
    if alphabet_size is None:
        raise ValueError("alphabet_size must be specified to determine the valid character set for counting.")
    if alphabet_size == 20:
        alphabet = np.array(list('ACDEFGHIKLMNPQRSTVWY'))
    elif alphabet_size == 4:
        alphabet = np.array(['A', 'C', 'G', 'T']) 
    
    counts = np.array([(alignment == aa).sum(axis=0) for aa in alphabet])
    total = counts.sum(axis=0)
    with np.errstate(divide='ignore', invalid='ignore'):
        p = np.where(counts > 0, counts / total, 0)
        log_p = np.where(p > 0, np.log2(p), 0)
    entropies = -(p * log_p).sum(axis=0)
    return entropies


def calculate_distribution_shape_features(values):
    from scipy import stats
    if len(values) < 10:
        return 0.0, 0.0
    skew = float(stats.skew(values))
    kurt = float(stats.kurtosis(values))
    if not np.isfinite(skew): skew = 0.0
    if not np.isfinite(kurt): kurt = 0.0
    return skew, kurt


def read_phylip_sequences(phylip_file):
    from Bio import SeqIO
    sequences = []
    for record in SeqIO.parse(phylip_file, "phylip-sequential"):
        sequences.append(str(record.seq))
    return sequences

def read_fasta_sequences(fasta_file):
    from Bio import SeqIO
    sequences = []
    for record in SeqIO.parse(fasta_file, "fasta"):
        sequences.append(str(record.seq))
    return sequences


def calculate_indel_features(sequences):
    """
    Indel features with transformations to reduce outlier impact:
    - avg_gap_size: log1p-transformed
    - msa_len: log-transformed
    - msa_max_len: divided by msa_len (fraction of alignment covered by longest seq)
    - msa_min_len: divided by msa_len (fraction of alignment covered by shortest seq)
    - tot_num_gaps: divided by (n_sequences * msa_len) → gap density
    """
    raw = msastats.calculate_msa_stats(sequences)[:9]
    avg_gap_size  = raw[0]
    msa_len       = raw[1]
    msa_max_len   = raw[2]
    msa_min_len   = raw[3]
    tot_num_gaps  = raw[4]
    n_seq = len(sequences)

    return {
        'avg_gap_size':            float(np.log1p(avg_gap_size)),
        'msa_len':                 float(np.log(msa_len)) if msa_len > 0 else 0.0,
        'msa_max_len':             float(msa_max_len / msa_len) if msa_len > 0 else 0.0,
        'msa_min_len':             float(msa_min_len / msa_len) if msa_len > 0 else 0.0,
        'tot_num_gaps':            float(tot_num_gaps / (n_seq * msa_len)) if (n_seq * msa_len) > 0 else 0.0,
        'num_gaps_len_one':        float(raw[5] / (n_seq * msa_len)) if (n_seq * msa_len) > 0 else 0.0,
        'num_gaps_len_two':        float(raw[6] / (n_seq * msa_len)) if (n_seq * msa_len) > 0 else 0.0,
        'num_gaps_len_three':      float(raw[7] / (n_seq * msa_len)) if (n_seq * msa_len) > 0 else 0.0,
        'num_gaps_len_at_least_four': float(raw[8] / (n_seq * msa_len)) if (n_seq * msa_len) > 0 else 0.0,
    }


def calculate_entropy_mi(msa_array, alphabet_size=None, gap_value=-1):
    if alphabet_size is None:
        raise ValueError("alphabet_size must be specified to determine the valid character set for counting.")
    """
    Calculates Shannon entropy per site and Mutual Information between adjacent sites
    while strictly ignoring gaps/missing data.
    
    Parameters:
    -----------
    msa_array : np.ndarray of shape (num_sequences, num_sites)
        An integer array where valid characters are mapped from 0 to alphabet_size-1.
    alphabet_size : int, optional (default=4)
        The size of the state space (4 for nucleotides, 20 for amino acids).
    gap_value : int, optional (default=-1)
        The integer value used to represent gaps or missing data in the matrix.
        
    Returns:
    --------
    entropies : np.ndarray of shape (num_sites,)
    mi_adjacent : np.ndarray of shape (num_sites - 1,)
    """
    num_seqs, num_sites = msa_array.shape
    
    # --- STEP 1: Compute Single-Site Entropies (Ignoring Gaps) ---
    # Create a mask of where valid data exists
    valid_mask = (msa_array != gap_value)
    # Count how many valid sequences exist per column (shape: num_sites,)
    valid_counts_per_site = np.sum(valid_mask, axis=0)
    
    # Count occurrences of valid states per column
    site_counts = np.array([np.sum(msa_array == i, axis=0) for i in range(alphabet_size)])
    
    # Calculate probabilities using the dynamic valid count per column
    # Avoid division by zero for completely empty columns by protecting with np.where
    safe_denominators = np.where(valid_counts_per_site > 0, valid_counts_per_site, 1)
    site_probs = site_counts / safe_denominators
    
    # Calculate Entropy
    entropies = -np.sum(site_probs * np.log2(np.where(site_probs > 0, site_probs, 1.0)), axis=0)
    # If a site is 100% gaps, force its entropy to 0.0
    entropies = np.where(valid_counts_per_site > 0, entropies, 0.0)
    
    # --- STEP 2: Compute Joint Entropies of Adjacent Pairs (Ignoring Gaps) ---
    left_sites = msa_array[:, :-1]
    right_sites = msa_array[:, 1:]
    
    # A pair is only valid if NEITHER position is a gap
    valid_pairs_mask = (left_sites != gap_value) & (right_sites != gap_value)
    valid_counts_per_pair = np.sum(valid_pairs_mask, axis=0)
    
    # Encode pairs to base-N
    pair_codes = left_sites * alphabet_size + right_sites
    # Force gap-containing pairs to an arbitrary safe value (e.g., 0) so they don't break indexing.
    # We will ignore their counts anyway using our valid_pairs_mask.
    pair_codes_masked = np.where(valid_pairs_mask, pair_codes, 0)
    
    num_pairs_possible = alphabet_size ** 2
    # Count pair configurations only where the pair mask is True
    joint_counts = np.array([np.sum((pair_codes_masked == i) & valid_pairs_mask, axis=0) 
                            for i in range(num_pairs_possible)])
    
    safe_pair_denominators = np.where(valid_counts_per_pair > 0, valid_counts_per_pair, 1)
    joint_probs = joint_counts / safe_pair_denominators
    
    # Calculate Joint Entropy
    joint_entropies = -np.sum(joint_probs * np.log2(np.where(joint_probs > 0, joint_probs, 1.0)), axis=0)
    joint_entropies = np.where(valid_counts_per_pair > 0, joint_entropies, 0.0)
    
    # --- STEP 3: Calculate Mutual Information ---
    h_x = entropies[:-1]
    h_y = entropies[1:]
    mi_adjacent = h_x + h_y - joint_entropies
    
    # If two adjacent sites share NO overlapping sequences (rare but possible with heavy gapping), 
    # force MI to 0.0 instead of leaving it as H(X) + H(Y)
    mi_adjacent = np.where(valid_counts_per_pair > 0, mi_adjacent, 0.0)
    mi_adjacent = np.clip(mi_adjacent, 0.0, None)
    
    return entropies, mi_adjacent


def compute_stats(values,prefix=''):

    skewness, kurtosis = calculate_distribution_shape_features(values)
    bimodality_coef = (skewness**2 + 1) / (kurtosis + 3)
    
    histogram_features = calculate_histogram(values, n_bins=10)

    histogram_features = {f'{prefix}_{k}': v for k, v in histogram_features.items()}
    histogram_features.update({
        f'{prefix}_skewness': float(np.clip(skewness, -10, 10)),
        f'{prefix}_kurtosis': float(np.clip(kurtosis, -10, 10)),
        f'{prefix}_bimodality_coefficient': bimodality_coef}
    )


    autocorr_features = calculate_autocorrelation_lags(values, max_lag=10)

    autocorr_features = {f'{prefix}_{k}': v for k, v in autocorr_features.items()}

    run_length_features = {}
    # if prefix == 'entropy':
    run_length_features = calculate_run_length_features(values)
    run_length_features = {f'{prefix}_{k}': v for k, v in run_length_features.items()}

    stats = {}
    stats.update({
        **histogram_features,
        **autocorr_features,
        **run_length_features,
    })
    return stats


def encode_msa_to_integers(string_msa_array, alphabet_size=None):
    """
    Optimized single-pass string-to-integer encoder using a lookup array.
    Maps valid characters to 0->(N-1) and all gaps/unrecognized characters to -1.
    """
    # Create an ASCII lookup array (256 slots) initialized to our gap value (-1)
    lookup = np.full(256, fill_value=-1, dtype=np.int32)
    
    # Fill in only the ASCII positions of our valid characters
    if alphabet_size == 20:
        alphabet = "ACDEFGHIKLMNPQRSTVWY"
    elif alphabet_size == 4:
        alphabet = "ACGT"
    else:
        raise ValueError("Unsupported alphabet size. Please specify either 4 (DNA) or 20 (Protein).")

    for idx, char in enumerate(alphabet):
        lookup[ord(char)] = idx
        # Map lowercase variants to the same index to stay case-insensitive
        lookup[ord(char.lower())] = idx
        
    # Convert string matrix to a raw 8-bit unsigned integer view (ASCII values)
    # This avoids Python string loops and lets NumPy do a direct index lookup
    ascii_view = string_msa_array.view('uint8')
    
    return lookup[ascii_view]

def calculate_all_features(sequences, alphabet_size=None) -> dict:
    if alphabet_size is None:
        raise ValueError("alphabet_size must be specified to determine the valid character set for counting.")
    """
    Single entry point for feature extraction used by both training and evaluation.
    Add or remove feature groups here — callers never need to change.
    """
    alignment = np.array([list(seq) for seq in sequences], dtype='S1')  # built once


    alignment_ints = encode_msa_to_integers(alignment, alphabet_size=alphabet_size)
    #number of taxa:
    entropies, mi_adjacent = calculate_entropy_mi(alignment_ints, alphabet_size=alphabet_size)  # Assuming DNA sequences with '-' as gap character
    mi_adjacent  = np.log1p(mi_adjacent)  # log1p-transform MI to reduce outlier impact (e.g. very high MI in small alignments)
    features = compute_stats(entropies, prefix='entropy')
    features.update(compute_stats(mi_adjacent, prefix='mi')) # mi stands for mutual information between adjacent sites

    features.update(calculate_indel_features(sequences))
    # add number of taxa, log-transformed to reduce outlier impact (e.g. very large trees)

    return features

def calculate_cnn_input(sequences, alphabet_size=None) -> torch.Tensor:
    alignment = np.array([list(seq) for seq in sequences], dtype='S1')

    encoded_msa = encode_msa_to_integers(alignment, alphabet_size=alphabet_size)

    entropies, mi_adjacent = calculate_entropy_mi(encoded_msa, alphabet_size=alphabet_size)
    mi_padded = np.append(mi_adjacent, 0.0)  # (499,) → (500,)
    return torch.tensor(
        np.stack([entropies, mi_padded], axis=0),  # (2, 500)
        dtype=torch.float32
    )

def get_feature_names():
    # Get feature names by running calculate_all_features on a dummy input
    dummy_sequences = ['ACGT', 'ACGT', 'ACGT']  # Minimal MSA with 3 identical sequences
    features = calculate_all_features(dummy_sequences, alphabet_size=4)
    return list(features.keys())

